	}

	blobHash, err := CreateBlobFromContent(s.repo, data)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
	}

	return object.TreeEntry{
